import { describe, expect, it } from "vitest";
import { markerVerdict } from "../../../utils/hunk-rules/generated";
import { lines } from "../../fixtures/head-scan";

describe("markerVerdict", () => {
  it.each([
    {
      path: "src/client/sdk.gen.ts",
      body: lines(
        "// This file is auto-generated by @hey-api/openapi-ts",
        "",
        'import type { Client } from "./client";',
      ),
      verdict: "generated",
    },
    {
      path: "api/types.pb.go",
      body: lines(
        "//go:build linux",
        "// +build linux",
        "",
        "// Code generated by protoc-gen-go. DO NOT EDIT.",
        "",
        "package api",
      ),
      verdict: "generated",
    },
    {
      path: "src/generated/schema.rs",
      body: lines("// @generated by fixture-schema", "pub struct Schema;"),
      verdict: "generated",
    },
    {
      path: "src/licensed.ts",
      body: lines(
        "/*",
        " * Copyright 2026 Example",
        " * SPDX-License-Identifier: MIT",
        " */",
        "",
        "// @generated",
        "export const a = 1;",
      ),
      verdict: "generated",
    },
    { path: "gen/models.py", body: lines("# @generated", "x = 1"), verdict: "generated" },
    { path: "gen/models.lua", body: lines("-- @generated", "local x = 1"), verdict: "generated" },
    {
      path: "api/crlf.go",
      body: lines("// Code generated by x. DO NOT EDIT.\r", "package api"),
      verdict: "generated",
    },
    {
      path: "src/late.ts",
      body: lines("export const a = 1;", "// @generated"),
      verdict: "not-generated",
    },
    {
      path: "src/by.ts",
      body: lines("// @generatedBy tool", "export const a = 1;"),
      verdict: "not-generated",
    },
    {
      path: "api/loose.go",
      body: lines("// Code generated by x. DO NOT EDIT. Really.", "package api"),
      verdict: "not-generated",
    },
    { path: "src/open.ts", body: lines("/*", " * a long license"), verdict: "needs-content" },
    { path: "data/schema.json", body: lines("// @generated", "{}"), verdict: "not-generated" },
  ])("reads $path as $verdict", ({ path, body, verdict }) =>
    expect(markerVerdict(path, body.split("\n"))).toBe(verdict),
  );
});
